package com.xdownload.mobile;
import android.content.*;import android.net.Uri;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.io.*;import java.net.*;import java.util.concurrent.atomic.AtomicBoolean;
@RunWith(AndroidJUnit4.class) public class TransferTest{
 @Test public void actualServicePublishesFile()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();byte[] bytes=new byte[128000];new java.util.Random(5).nextBytes(bytes);ServerSocket server=new ServerSocket(0,5,InetAddress.getByName("127.0.0.1"));AtomicBoolean stop=new AtomicBoolean();Thread t=new Thread(()->{while(!stop.get())try(Socket sock=server.accept()){BufferedReader r=new BufferedReader(new InputStreamReader(sock.getInputStream()));String first=r.readLine(),line;while((line=r.readLine())!=null&&!line.isEmpty()){}OutputStream out=sock.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: "+bytes.length+"\r\nETag: \"test\"\r\nConnection: close\r\n\r\n").getBytes());if(first!=null&&first.startsWith("GET"))out.write(bytes);out.flush();}catch(Exception ignored){}});t.start();Store.settings(c).edit().putBoolean("http",true).putBoolean("wifi",false).putBoolean("battery",false).putInt("mode",1).commit();String url="http://127.0.0.1:"+server.getLocalPort()+"/sample.bin";Store.Job job=new Store.Job(url,new HttpEngine.Info("xdownload-test.bin","application/octet-stream",bytes.length,"","",true),"");Store.get(c).add(job);try(ActivityScenario<MainActivity> a=ActivityScenario.launch(MainActivity.class)){a.onActivity(v->TransferService.command(v,"start",job.id));long until=android.os.SystemClock.elapsedRealtime()+30000;while(android.os.SystemClock.elapsedRealtime()<until){synchronized(Store.get(c)){if(job.state.equals("complete")||job.state.equals("error"))break;}Thread.sleep(100);}assertEquals(job.error,"complete",job.state);assertEquals(bytes.length,job.done);assertEquals(64,job.sha.length());try(InputStream in=c.getContentResolver().openInputStream(Uri.parse(job.uri));ByteArrayOutputStream out=new ByteArrayOutputStream()){assertNotNull(in);byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);assertArrayEquals(bytes,out.toByteArray());}}finally{stop.set(true);server.close();t.join(2000);if(!job.uri.isEmpty())c.getContentResolver().delete(Uri.parse(job.uri),null,null);c.stopService(new Intent(c,TransferService.class));Store.settings(c).edit().clear().commit();}}
}